export function decide(x) {
  if (x.actorOwner !== x.courseOwner || x.role !== 'coach') return {outcome:'DENIED',writes:0};
  if (!x.title.trim()) return {outcome:'INVALID',writes:0};
  if (x.requestKnown) return {outcome:'REPLAY',writes:0};
  if (x.expectedRevision !== x.currentRevision) return {outcome:'STALE',writes:0};
  return {outcome:'CREATED',writes:1};
}

